import java.io.InputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    buflen = -1;
                }
                return buflen > 0;
            }
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        public int nextInt() {
            int b = readByte();
            while (b <= ' ' && b != -1) {
                b = readByte();
            }
            if (b == -1) return -1;
            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return res;
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        int n = scanner.nextInt();
        if (n <= 1) {
            System.out.println(0);
            return;
        }

        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }

        int i = 0;
        int j = n - 1;
        long sumL = a[i];
        long sumR = a[j];
        int ops = 0;

        while (i < j) {
            if (sumL == sumR) {
                i++;
                j--;
                sumL = a[i];
                sumR = a[j];
            } else if (sumL < sumR) {
                i++;
                sumL += a[i];
                ops++;
            } else {
                j--;
                sumR += a[j];
                ops++;
            }
        }

        System.out.println(ops);
    }
}
